# Compare byte by byte
max_len = max(len(bytes_4F), len(bytes_50))
diffs = []

for i in range(max_len):
    if i < len(bytes_4F) and i < len(bytes_50):
        if bytes_4F[i] != bytes_50[i]:
            diffs.append((i, bytes_4F[i] if i < len(bytes_4F) else None, bytes_50[i] if i < len(bytes_50) else None))
    else:
        diffs.append((i, bytes_4F[i] if i < len(bytes_4F) else None, bytes_50[i] if i < len(bytes_50) else None))

if diffs:
    print(f"\nFound {len(diffs)} difference(s):\n")
    for pos, b4f, b50 in diffs:
        b4f_str = f"0x{b4f:02X}" if b4f is not None else "---"
        b50_str = f"0x{b50:02X}" if b50 is not None else "---"
        print(f"  Byte {pos:3d}: 0x4F={b4f_str}  vs  0x50={b50_str}")
else:
    print("\nPackets are IDENTICAL!")

print("\n" + "=" * 80)
